parameters.jsCode:
// Extract note content and metadata
const note = $input.item.json;

return {
  original_content: note.content || note.text || note.body,
  note_id: note.id,
  timestamp: note.created_at || new Date().toISOString(),
  tags: note.tags || [],
  metadata: note
};

// Parse Ollama response and merge with original note
const original = $input.first().json;
const ollamaResponse = $input.item.json;

// Extract the response text
let analysisText = ollamaResponse.response;

// Try to parse as JSON
let analysis = {};
try {
  analysis = JSON.parse(analysisText);
} catch (e) {
  // If not valid JSON, extract what we can
  analysis = {
    tags: [],
    summary: analysisText.substring(0, 200),
    entities: [],
    connections: []
  };
}

return {
  original_content: original.original_content,
  note_id: original.note_id,
  timestamp: original.timestamp,
  ai_tags: analysis.tags || [],
  ai_summary: analysis.summary || '',
  ai_entities: analysis.entities || [],
  ai_connections: analysis.connections || [],
  enriched_at: new Date().toISOString()
};

